__NUXT_JSONP__("/posts/red-teamer-building-a-button-based-ai-chatbot-game", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N,O){return {data:[{post:{slug:v,description:"My journey building an AI-powered button-based chatbot.",title:"Red Teamer: Building a Button-Based AI Chatbot Game",type:h,imgCover:v,tags:["game",w,"framer-motion","Tailwind","Figma",t,u,"AI",h],createdAt:"2025-09-07T00:00:00.000Z",toc:[{id:x,depth:g,text:y},{id:z,depth:g,text:A},{id:B,depth:g,text:C},{id:D,depth:g,text:E},{id:F,depth:g,text:G},{id:H,depth:g,text:I}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"This post is about "},{type:b,tag:e,props:{href:J,rel:[o,p,q],target:r},children:[{type:a,value:"Red Teamer"}]},{type:a,value:": the small game I had developed."}]},{type:a,value:c},{type:b,tag:i,props:{id:x},children:[{type:b,tag:e,props:{href:"#context",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:y}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A couple of months have passed since my latest "},{type:b,tag:"nuxt-link",props:{to:"\u002Fposts\u002Fbuilding-a-narrative-game-whith-nextjs-and-ai"},children:[{type:a,value:"narrative game"}]},{type:a,value:" and it was time to tackle a new project."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I wanted to bring AI into the equation in some way, as it is definitely reshaping our digital interactions."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I started a new job as a front-end engineer at "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.giskard.ai\u002F",rel:[o,p,q],target:r},children:[{type:a,value:"Giskard"}]},{type:a,value:" a couple of months ago."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It's a French startup which offers a platform to help identify failures for teams developing AI agents. I familiarized myself with the concept of \"red teaming\", which is the practice of simulating attacks against someone's product to patch it and improve its robustness."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.giskard.ai\u002Fproducts\u002Fllm-evaluation",rel:[o,p,q],target:r},children:[{type:a,value:"Giskard hub"}]},{type:a,value:" performs a vulnerabilities classification from the "},{type:b,tag:e,props:{href:"https:\u002F\u002Fowasp.org\u002Fwww-project-top-10-for-large-language-model-applications\u002F",rel:[o,p,q],target:r},children:[{type:a,value:"OWASP Top 10 LLM"}]},{type:a,value:" definitions."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I had the idea of a small game to better understand these vulnerabilities through live examples."}]},{type:a,value:c},{type:b,tag:i,props:{id:z},children:[{type:b,tag:e,props:{href:"#concept",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:A}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The game core is a button-based chatbot in which the user chooses a vulnerability to learn. An attack is then launched, prompting an agent testing the chosen vulnerability. The agent response is either successful (he defended properly) or unsuccessful (he fails and falls into the trap, exposing its vulnerability)."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Depending on the given response, the user has to assess how the agent has responded."}]},{type:a,value:c},{type:b,tag:i,props:{id:B},children:[{type:b,tag:e,props:{href:"#visual",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:C}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I chose to represent the attacker and the bot using 3D avatars:"}]},{type:a,value:c},{type:b,tag:K,props:{},children:[{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"a turtle for the tester (taken from the Giskard identity)"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"an android for the agent"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"As usual, I made them by highly customizing base models and rendered them using Redshift along with C4D. This latter has become the standard and now supports cell and toon shading. Its node-based system is not very intuitive at first, but very powerful. I really appreciated working with live-render though."}]},{type:a,value:c},{type:b,tag:L,props:{src:"https:\u002F\u002Fres.cloudinary.com\u002Flansolo99\u002Fimage\u002Fupload\u002Fc_fit,dpr_auto,q_auto,w_auto\u002Fv1757161657\u002Flansolo.dev\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game-3D.jpg",alt:"Red Teamer - 3D turtle asset"},children:[]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I gathered the avatars on a scene, and set a bunch of animated loops to use in the game, bringing a \"living\" UI that I find appealing."}]},{type:a,value:c},{type:b,tag:L,props:{src:"https:\u002F\u002Fres.cloudinary.com\u002Flansolo99\u002Fimage\u002Fupload\u002Fc_fit,dpr_auto,q_auto,w_auto\u002Fv1757161672\u002Flansolo.dev\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game-gameboard.jpg",alt:"Red Teamer - gameboard scene"},children:[]},{type:a,value:c},{type:b,tag:i,props:{id:D},children:[{type:b,tag:e,props:{href:"#stack",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:E}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"On this side, I went with Next.js + Motion."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"For the AI part, I chose Google Gemini through Vercel's AI SDK primarily for cost efficiency. The AI SDK with Zod schemas is very easy to implement and ensures reliable structured responses, returning not just the attack conversation but also success assessment and analysis explanations that feed the game's scoring system."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I thought this would take me a day to build, but I had a working feature within 2 hours. The most time-consuming part was the prompting logic to frame the result and avoid hallucinations (exactly what the game puts the light on)."}]},{type:a,value:c},{type:b,tag:i,props:{id:F},children:[{type:b,tag:e,props:{href:"#coding-assistant",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:G}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I started the app using Cursor Agent, then switched to Claude Code, driven by a general consensus on it at the moment."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The terminal flow is surprisingly as pleasant as a standard UI and extends to some very interesting possibilities:"}]},{type:a,value:c},{type:b,tag:K,props:{},children:[{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"\u002Finit feature: to help Claude understand the whole app's purpose and architecture"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"plan mode: to monitor a step-by-step approach"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"bash mode: to launch bash commands and have a direct Claude feedback on them"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"memories: to save user behaviors and rules"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"\u002Fmcp feature: to add some mcps"}]},{type:a,value:c},{type:b,tag:f,props:{},children:[{type:a,value:"images feed: to build by giving a visual feedback (frontend bugs, UI mockups...)"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The code quality is recognized as very qualitative compared to others solutions."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I indeed experienced a really good flow, generating 75% of the code."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The only part I had to take care of myself is fine-tuning the UI & animations: the coding assistants are good to build something functional with a standard UI, but don't have the design sensibility to ship a well-polished UI."}]},{type:a,value:c},{type:b,tag:i,props:{id:H},children:[{type:b,tag:e,props:{href:"#wrapping-up",ariaHidden:j,tabIndex:k},children:[{type:b,tag:l,props:{className:[m,n]},children:[]}]},{type:a,value:I}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"I intend to maybe gamify the app by implementing authentication along with a scoreboard, with some levels to reach. That would help engage the user in their learning."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"You can test "},{type:b,tag:e,props:{href:J,rel:[o,p,q],target:r},children:[{type:a,value:"Red Teamer here"}]},{type:a,value:"."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"In the end, this was a nice side-project. I realize how AI assistants make app development easier. Although solid knowledge is required to ship something clean, these tools open the door to building projects at an unprecedented pace."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"We’ll see where all this will lead us..."}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game",extension:".md",updatedAt:"2025-10-10T15:29:17.527Z"},relatedPosts:[{title:"Material Tailwind quick review",type:h,imgCover:"material-tailwind-quick-review.jpg",tags:[w,"tailwind","form","miscs",t,h],createdAt:"2022-07-25T00:00:00.000Z",path:"\u002Fposts\u002Fmaterial-tailwind-quick-review"},{title:"Building Meet Harvey:  a dive into Wordpress membership plugin",type:h,imgCover:"building-meet-harvey-a-dive-into-wordpress-membership-plugin",tags:["wordpress",t,h],createdAt:"2019-10-11T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-meet-harvey-a-dive-into-wordpress-membership-plugin"},{title:"Gandi.net datacenter migration",type:s,imgCover:"gandi-net-datacenter-migration",tags:[u,M,N,"after effects",O,s],createdAt:"2018-04-10T00:00:00.000Z",path:"\u002Fposts\u002Fgandi-net-datacenter-migration"},{title:"Gandi's kitchen",type:s,imgCover:"gandis-kitchen",tags:[u,M,N,O,s],createdAt:"2017-11-13T00:00:00.000Z",path:"\u002Fposts\u002Fgandis-kitchen"}]}],fetch:[{counter:4},{counter:26},{counter:14},{counter:13},{counter:12},{counter:32},{counter:53},{counter:g},{counter:72}],mutations:[]}}("text","element","\n","p","a","li",2,"article","h2","true",-1,"span","icon","icon-link","nofollow","noopener","noreferrer","_blank","design","devs","cinema 4D","red-teamer-building-a-button-based-ai-chatbot-game","next","context","Context","concept","Concept","visual","Visual","stack","Stack","coding-assistant","Coding assistant","wrapping-up","Wrapping-up","https:\u002F\u002Fred-teamer-alpha.vercel.app\u002F","ul","img","low poly","sketch & toon","artworks")));